// src/app/notifications/page.jsx
"use client";

import AppLayout from "@/components/AppLayout";
import { useEffect, useState } from "react";
import { useSocket } from "@/contexts/SocketContext";
import { useAuth } from "@/contexts/AuthContext";
import Link from "next/link";

export default function NotificationsPage() {
  const socket = useSocket();
  const { user } = useAuth();
  const [notifications, setNotifications] = useState([]);

  // 1) Fetch initial notifications from your API
  useEffect(() => {
    if (!user) return;
    fetch("/api/notifications", { credentials: "include" })
      .then((res) => res.json())
      .then((data) => setNotifications(data.notifications || []))
      .catch(console.error);
  }, [user]);

  // 2) Subscribe to real-time pushes
  useEffect(() => {
    if (!socket) return;
    const handler = (notif) => {
      setNotifications((prev) => [notif, ...prev]);
    };
    socket.on("notification", handler);
    return () => void socket.off("notification", handler);
  }, [socket]);

  return (
    <AppLayout>
      <div className="p-6 space-y-6">
        <h1 className="text-2xl font-bold">Notifications</h1>

        {notifications.length === 0 ? (
          <p className="text-gray-500">You have no notifications.</p>
        ) : (
          <ul className="space-y-4 max-h-[70vh] overflow-y-auto">
            {notifications.map((notif, i) => (
              <li
                key={i}
                className="bg-white p-4 rounded-lg shadow hover:bg-gray-50 transition"
              >
                <Link
                  href={notif.post_id ? `/posts/${notif.post_id}` : "#"}
                  className="flex items-start gap-3"
                >
                  {/* sender avatar placeholder */}
                  <div className="w-10 h-10 rounded-full bg-gray-300 flex-shrink-0" />
                  <div>
                    <p className="text-sm text-gray-800">
                      <span className="font-semibold">
                        {notif.sender_name || "Someone"}
                      </span>{" "}
                      <span className="text-pink-600">
                        {notif.message ||
                          notif.type ||
                          "sent you a notification"}
                      </span>
                    </p>
                    <p className="text-xs text-gray-400 mt-1">
                      {notif.created_at
                        ? new Date(notif.created_at).toLocaleString()
                        : "Just now"}
                    </p>
                  </div>
                </Link>
              </li>
            ))}
          </ul>
        )}
      </div>
    </AppLayout>
  );
}
